INSERT INTO public.quiz_questions (quiz, qkey, ur, en, options, answer) VALUES
  ('rules', 'rules:fee', 'پیچکس درخواست دینے کے کتنے پیسے لیتا ہے؟', 'How much does Pechkas charge you to apply?', '[{"ur": "ایک ہزار روپے", "en": "Rs 1,000"}, {"ur": "کچھ بھی نہیں، کبھی نہیں", "en": "Nothing, ever"}, {"ur": "پہلے کام سے کاٹ لیے جاتے ہیں", "en": "It is taken from the first job"}]'::jsonb, 1),
  ('rules', 'rules:cnic', 'کیا آپ آفر، پیغام یا نوٹ میں اپنا شناختی کارڈ نمبر لکھ سکتے ہیں؟', 'May you write your CNIC number in an offer, a message or a note?', '[{"ur": "نہیں، کبھی نہیں", "en": "No, never"}, {"ur": "ہاں، اگر گاہک مانگے", "en": "Yes, if the customer asks"}, {"ur": "صرف چیٹ میں", "en": "Only in the chat"}]'::jsonb, 0),
  ('rules', 'rules:number', 'گاہک کے آپ کو چننے سے پہلے، کیا آپ اسے اپنا فون نمبر دے سکتے ہیں؟', 'Before a customer chooses you, may you give her your phone number?', '[{"ur": "نہیں", "en": "No"}, {"ur": "ہاں", "en": "Yes"}, {"ur": "صرف آفر کے نوٹ میں", "en": "Only in the note on your offer"}]'::jsonb, 0),
  ('rules', 'rules:bigger', 'کام پر پہنچ کر پتہ چلتا ہے کہ کام بتائے گئے سے زیادہ ہے۔ آپ کیا کریں گے؟', 'At the job you find more work than was described. What do you do?', '[{"ur": "ایپ میں نئی قیمت، وجہ اور تصویر کے ساتھ بھیجیں", "en": "Send the new price in the app, with the reason and a photo"}, {"ur": "دروازے پر زیادہ پیسے مانگیں", "en": "Ask for more money at the door"}, {"ur": "کام کر کے آخر میں زیادہ پیسے لیں", "en": "Do it and charge more at the end"}]'::jsonb, 0),
  ('rules', 'rules:code', 'آپ کام کب شروع کر سکتے ہیں؟', 'When may you start the work?', '[{"ur": "پہنچتے ہی", "en": "As soon as you arrive"}, {"ur": "گاہک کے اسٹارٹ کوڈ دینے کے بعد", "en": "After the customer gives you the start code"}, {"ur": "جب دفتر کہے", "en": "When the office tells you"}]'::jsonb, 1),
  ('rules', 'rules:photos', 'کام شروع کرتے وقت اور ختم کرتے وقت ایپ میں کیا کرنا ضروری ہے؟', 'What must you do in the app when you start and when you finish?', '[{"ur": "کام کی تصویریں لیں", "en": "Take photos of the work"}, {"ur": "کچھ نہیں", "en": "Nothing"}, {"ur": "دفتر کو وائس نوٹ بھیجیں", "en": "Send a voice note to the office"}]'::jsonb, 0),
  ('rules', 'rules:parts', 'پرزوں کے پیسے گاہک سے کیسے لیے جاتے ہیں؟', 'How are parts charged to the customer?', '[{"ur": "جو قیمت آپ چاہیں", "en": "At any price you choose"}, {"ur": "دکان کی قیمت کا دگنا", "en": "Double the shop price"}, {"ur": "دکان کی قیمت پر، رسید کی تصویر کے ساتھ", "en": "At the shop''s price, with a photo of the receipt"}]'::jsonb, 2),
  ('rules', 'rules:visitfee', 'وزٹ فیس کب بنتی ہے؟', 'When is a visit fee owed?', '[{"ur": "جب مرمت ہو جائے", "en": "When the repair goes ahead"}, {"ur": "جب کام شروع ہونے کے بعد گاہک نئی قیمت سے انکار کرے", "en": "When the customer says no to a new price after you have started"}, {"ur": "جب بھی آپ دیر سے پہنچیں", "en": "Whenever you arrive late"}]'::jsonb, 1),
  ('rules', 'rules:gasleak', 'کیا پیچکس گیس لیک کی مرمت کرتا ہے؟', 'Does Pechkas repair gas leaks?', '[{"ur": "نہیں", "en": "No"}, {"ur": "صرف اتوار کو", "en": "Only on Sundays"}, {"ur": "ہاں", "en": "Yes"}]'::jsonb, 0),
  ('rules', 'rules:cooker', 'ایک گاہک گیس کے چولہے کی مرمت "کچھ اور" کے طور پر پوسٹ کرتا ہے۔ آپ کیا کریں گے؟', 'A customer posts a gas cooker repair as "Something else". What do you do?', '[{"ur": "کام کر دیں اور کسی کو نہ بتائیں", "en": "Do it and tell nobody"}, {"ur": "اس پر آفر دیں", "en": "Offer on it"}, {"ur": "انکار کریں: پیچکس گیس کے چولہے یا اوون کا کام نہیں لیتا", "en": "Decline it: Pechkas does not take gas cooker or oven work"}]'::jsonb, 2),
  ('rules', 'rules:notfinished', 'گاہک "ابھی مکمل نہیں" دباتا ہے۔ آپ کیا کریں گے؟', 'The customer taps "Not finished yet". What do you do?', '[{"ur": "کام ٹھیک کریں، پھر دوبارہ \"کام مکمل\" دبائیں", "en": "Put it right, then tap \"Work finished\" again"}, {"ur": "کام چھوڑ کر چلے جائیں", "en": "Leave the job"}, {"ur": "بحث کریں جب تک وہ مان نہ جائے", "en": "Argue until she agrees"}]'::jsonb, 0),
  ('rules', 'rules:outside', 'کیا آپ ایپ کے ذریعے ملنے والے گاہک کے ساتھ ایپ سے باہر کام طے کر سکتے ہیں؟', 'May you agree to do a job outside the app with a customer you met through it?', '[{"ur": "ہاں", "en": "Yes"}, {"ur": "نہیں", "en": "No"}, {"ur": "صرف اگر اس کے لیے سستا ہو", "en": "Only if it is cheaper for her"}]'::jsonb, 1),
  ('rules', 'rules:rating', 'کیا آپ اچھی ریٹنگ کے بدلے گاہک کو کچھ پیش کر سکتے ہیں؟', 'May you offer a customer anything for a good rating?', '[{"ur": "نہیں", "en": "No"}, {"ur": "ہاں", "en": "Yes"}, {"ur": "صرف تھوڑی رعایت", "en": "A small discount only"}]'::jsonb, 0),
  ('rules', 'rules:danger', 'کام پر آپ خطرے میں ہیں۔ آپ سب سے پہلے کیا دبائیں گے؟', 'You are in danger at a job. What do you press first?', '[{"ur": "ایمرجنسی بٹن", "en": "The emergency button"}, {"ur": "چیٹ", "en": "Chat"}, {"ur": "کام مکمل", "en": "Work finished"}]'::jsonb, 0),
  ('rules', 'rules:cantcome', 'جس کام کے لیے آپ کو چنا گیا، آپ وہاں نہیں جا سکتے۔ آپ کیا کریں گے؟', 'You cannot come to a job you were chosen for. What do you do?', '[{"ur": "جتنی جلدی ہو سکے ایپ میں \"میں نہیں آ سکتا\" دبائیں", "en": "Tap \"I can''t come\" in the app as early as you can"}, {"ur": "فون بند کر دیں", "en": "Switch your phone off"}, {"ur": "کسی اور کو بھیج دیں", "en": "Send somebody else"}]'::jsonb, 0),
  ('rules', 'rules:late', 'آپ کو دیر ہونے والی ہے۔ آپ کیا کریں گے؟', 'You are going to be late. What do you do?', '[{"ur": "ایپ میں \"مجھے دیر ہو رہی ہے\" دبائیں، پہنچنے کے وقت کے ساتھ", "en": "Tap \"I''m running late\" in the app, with the time you will arrive"}, {"ur": "کچھ نہ کہیں", "en": "Say nothing"}, {"ur": "پہلے کسی اور کام پر جائیں", "en": "Go to another job first"}]'::jsonb, 0),
  ('rules', 'rules:unsafe', 'گاہک ایسا کام مانگتا ہے جو آپ کے خیال میں غیر محفوظ ہے۔ آپ کیا کریں گے؟', 'A customer asks for work you think is unsafe. What do you do?', '[{"ur": "انکار کریں", "en": "Refuse it"}, {"ur": "زیادہ پیسوں پر کر دیں", "en": "Do it if she pays more"}, {"ur": "جلدی سے کر دیں", "en": "Do it quickly"}]'::jsonb, 0),
  ('rules', 'rules:roof', 'آپ چھت پر ہیں اور بارش شروع ہو جاتی ہے۔ آپ کیا کریں گے؟', 'You are on a roof and it starts to rain. What do you do?', '[{"ur": "خشک رہنے کے لیے پینلز پر کھڑے ہو جائیں", "en": "Stand on the panels to keep dry"}, {"ur": "کام روکیں اور احتیاط سے نیچے آئیں", "en": "Stop and come down safely"}, {"ur": "جلدی ختم کریں", "en": "Finish quickly"}]'::jsonb, 1),
  ('rules', 'rules:firstjobs', 'کسی کام کی قسم میں اپنے پہلے کاموں میں آپ کون سے کام لے سکتے ہیں؟', 'On your first jobs in a trade, which jobs may you take?', '[{"ur": "کوئی بھی کام", "en": "Any job at all"}, {"ur": "صرف خطرناک کام", "en": "Only risky jobs"}, {"ur": "صرف بنیادی کام، ایک وقت میں ایک، قیمت کی حد تک", "en": "Basic jobs only, one at a time, up to the price limit"}]'::jsonb, 2),
  ('rules', 'rules:face', 'گاہک دروازے پر آپ کی تصویر کیوں دیکھتی ہے؟', 'Why does the customer check your photo at her door?', '[{"ur": "اس کی ضرورت نہیں", "en": "It is not needed"}, {"ur": "یہ یقینی بنانے کے لیے کہ آپ وہی ہیں جسے ایپ نے بھیجا", "en": "To make sure you are the man the app sent"}, {"ur": "آپ کی شکل کو ریٹ کرنے کے لیے", "en": "To rate your looks"}]'::jsonb, 1),
  ('rules', 'rules:claim', 'گاہک کہتی ہے کہ آپ کی مرمت گارنٹی کے اندر خراب ہو گئی۔ آپ کیا کریں گے؟', 'A customer says your repair failed within the guarantee. What do you do?', '[{"ur": "اسے بلاک کریں", "en": "Block her"}, {"ur": "نظر انداز کریں", "en": "Ignore it"}, {"ur": "ایپ میں دکھائے گئے وقت کے اندر جواب دیں", "en": "Answer in the app within the time it shows"}]'::jsonb, 2),
  ('rules', 'rules:address', 'آپ گاہک کا پتہ اور نمبر کس لیے استعمال کر سکتے ہیں؟', 'What may you use a customer''s address and number for?', '[{"ur": "بعد میں اسے دوسرا کام پیش کرنے کے لیے", "en": "To offer her other work later"}, {"ur": "کسی دوست کو دینے کے لیے", "en": "To give to a friend"}, {"ur": "صرف اسی کام کے لیے", "en": "Only for that job"}]'::jsonb, 2),
  ('rules', 'rules:collect', 'آپ گاہک سے کتنے پیسے لیتے ہیں؟', 'How much do you collect from the customer?', '[{"ur": "طے شدہ قیمت کے ساتھ ٹپ", "en": "The agreed price plus a tip"}, {"ur": "جتنی رقم ایپ دکھاتی ہے", "en": "The amount the app shows"}, {"ur": "آخر میں جو وہ مان جائے", "en": "Whatever she agrees to at the end"}]'::jsonb, 1),
  ('rules', 'rules:paypechkas', 'آپ پیچکس کے واجب پیسے کیسے ادا کرتے ہیں؟', 'How do you pay what you owe Pechkas?', '[{"ur": "کسی گاہک کو دے دیں", "en": "Give it to a customer"}, {"ur": "رقم بھیجیں، پھر مائی اکاؤنٹ میں \"میں نے ادا کر دیا\" دبائیں", "en": "Send it, then tap \"I have paid\" in My account"}, {"ur": "کبھی کچھ واجب نہیں ہوتا", "en": "Nothing is ever owed"}]'::jsonb, 1),
  ('safety:ac', 'ac:isolate', 'اے سی کھولنے سے پہلے سب سے پہلے کیا کرتے ہیں؟', 'Before you open an AC, what do you do first?', '[{"ur": "اس کا بریکر بند کریں", "en": "Switch it off at its breaker"}, {"ur": "فین موڈ پر کر دیں", "en": "Turn it to fan mode"}, {"ur": "کچھ نہیں", "en": "Nothing"}]'::jsonb, 0),
  ('safety:ac', 'ac:leaktest', 'گیس ڈالنے سے پہلے جوڑوں میں لیک کیسے چیک کرتے ہیں؟', 'Before adding gas, how do you check the joints for a leak?', '[{"ur": "صابن والے پانی یا لیک ڈیٹیکٹر سے", "en": "With soapy water or a leak detector"}, {"ur": "آگ سے", "en": "With a flame"}, {"ur": "سونگھ کر", "en": "By smell"}]'::jsonb, 0),
  ('safety:ac', 'ac:r32', 'کچھ اے سی گیسیں، جیسے R32، آگ پکڑ سکتی ہیں۔ ان کے قریب کس چیز سے بچتے ہیں؟', 'Some AC gases, such as R32, can burn. What do you avoid near them?', '[{"ur": "پانی", "en": "Water"}, {"ur": "دستانے", "en": "Gloves"}, {"ur": "آگ اور چنگاریاں", "en": "Flames and sparks"}]'::jsonb, 2),
  ('safety:ac', 'ac:cylinder', 'گیس سلنڈر کیسے رکھتے ہیں؟', 'How do you keep a gas cylinder?', '[{"ur": "گرم گاڑی میں لٹا کر", "en": "Lying down in a hot car"}, {"ur": "سیدھا، بندھا ہوا، گرمی اور دھوپ سے دور", "en": "Upright, secured, away from heat and sun"}, {"ur": "کہیں بھی", "en": "Anywhere"}]'::jsonb, 1),
  ('safety:ac', 'ac:capacitor', 'کیپیسیٹر کے ٹرمینل چھونے سے پہلے کیا کرتے ہیں؟', 'What do you do with a capacitor before touching its terminals?', '[{"ur": "گیلا کریں", "en": "Wet it"}, {"ur": "کچھ نہیں", "en": "Nothing"}, {"ur": "اسے محفوظ طریقے سے ڈسچارج کریں", "en": "Discharge it safely"}]'::jsonb, 2),
  ('safety:ac', 'ac:bracket', 'آؤٹ ڈور یونٹ کا بریکٹ کیسے لگایا جاتا ہے؟', 'How must an outdoor unit bracket be fixed?', '[{"ur": "کھڑکی پر رکھ کر", "en": "Resting on the window"}, {"ur": "تار سے", "en": "With wire"}, {"ur": "مضبوط دیوار پر صحیح بولٹس کے ساتھ", "en": "To a solid wall with the right bolts"}]'::jsonb, 2),
  ('safety:ac', 'ac:height', 'دیوار پر اونچائی پر لگے آؤٹ ڈور یونٹ پر کام کرتے ہوئے آپ کو کیا محفوظ رکھتا ہے؟', 'Working on an outdoor unit high on a wall, what keeps you safe?', '[{"ur": "کرسی پر کھڑے ہو کر", "en": "Standing on a chair"}, {"ur": "مضبوط سیڑھی جو پکڑی یا بندھی ہو، اور جہاں ضرورت ہو سیفٹی بیلٹ", "en": "A sound ladder held or tied, and a safety belt where needed"}, {"ur": "کھڑکی سے جھک کر", "en": "Leaning out of the window"}]'::jsonb, 1),
  ('safety:ac', 'ac:earth', 'کیا اے سی کی ارتھ تار جڑی رہنی چاہیے؟', 'Should the AC earth wire be left connected?', '[{"ur": "ہاں، ہمیشہ", "en": "Yes, always"}, {"ur": "صرف گرمیوں میں", "en": "Only in summer"}, {"ur": "نہیں، ضرورت نہیں", "en": "No, it is not needed"}]'::jsonb, 0),
  ('safety:ac', 'ac:cable', 'بریکر سے اے سی تک کون سی تار استعمال کرتے ہیں؟', 'What cable do you use from the breaker to the AC?', '[{"ur": "جس سائز کی اے سی اور بریکر کو ضرورت ہو", "en": "The size the AC and breaker need"}, {"ur": "ایکسٹینشن لیڈ", "en": "An extension lead"}, {"ur": "جو بھی پتلی تار ہو", "en": "Any thin wire you have"}]'::jsonb, 0),
  ('safety:ac', 'ac:frost', 'ریفریجرینٹ کے ساتھ کام کرتے ہوئے دستانے اور چشمہ کیوں پہنتے ہیں؟', 'Why wear gloves and glasses when handling refrigerant?', '[{"ur": "کوئی وجہ نہیں", "en": "There is no reason"}, {"ur": "یہ جلد کو جما سکتا ہے اور آنکھوں کو نقصان دے سکتا ہے", "en": "It can freeze skin and hurt the eyes"}, {"ur": "دکھاوے کے لیے", "en": "For looks"}]'::jsonb, 1),
  ('safety:ac', 'ac:vent', 'کیا کمرے میں ریفریجرینٹ چھوڑ سکتے ہیں؟', 'May you release refrigerant into a room?', '[{"ur": "اگر کھڑکی کھلی ہو", "en": "If the window is open"}, {"ur": "نہیں", "en": "No"}, {"ur": "ہاں", "en": "Yes"}]'::jsonb, 1),
  ('safety:ac', 'ac:gauges', 'کیسے پتہ چلتا ہے کہ کتنی گیس ڈالنی ہے؟', 'How do you know how much gas to add?', '[{"ur": "گیجز اور کمپنی کے بتائے گئے پیمانے سے", "en": "Use gauges and the maker''s figures"}, {"ur": "اندازے سے", "en": "Guess"}, {"ur": "جب تک بھرے", "en": "Fill until it stops"}]'::jsonb, 0),
  ('safety:ac', 'ac:burning', 'اے سی سے جلنے کی بو آ رہی ہے۔ آپ کیا کریں گے؟', 'An AC smells of burning. What do you do?', '[{"ur": "بند کریں اور دوبارہ چلانے سے پہلے وجہ تلاش کریں", "en": "Switch it off and find the cause before running it again"}, {"ur": "اس پر پانی چھڑکیں", "en": "Spray water on it"}, {"ur": "تیز کر دیں", "en": "Turn it up"}]'::jsonb, 0),
  ('safety:ac', 'ac:wet', 'بجلی کے قریب فرش پر پانی ہے۔ آپ کیا کریں گے؟', 'There is water on the floor near the electrics. What do you do?', '[{"ur": "جلدی کام کریں", "en": "Work quickly"}, {"ur": "گیلے کپڑے پر کھڑے ہوں", "en": "Stand on a wet cloth"}, {"ur": "بجلی بند کریں اور کام سے پہلے خشک کریں", "en": "Switch off and dry it before working"}]'::jsonb, 2),
  ('safety:ac', 'ac:drill', 'انڈور یونٹ کے لیے دیوار میں ڈرل کرنے سے پہلے کیا چیک کرتے ہیں؟', 'Before drilling a wall for an indoor unit, what do you check?', '[{"ur": "دیوار کا رنگ", "en": "The colour of the wall"}, {"ur": "کچھ نہیں", "en": "Nothing"}, {"ur": "چھپی ہوئی تاریں اور پائپ", "en": "For hidden wires and pipes"}]'::jsonb, 2),
  ('safety:ac', 'ac:drain', 'ڈرین کا پانی کہاں جانا چاہیے؟', 'Where must the drain water go?', '[{"ur": "فرش پر", "en": "Onto the floor"}, {"ur": "باہر، تاروں اور کمرے سے دور", "en": "Outside, away from wiring and the room"}, {"ur": "ساکٹ کے ڈبے میں", "en": "Into the socket box"}]'::jsonb, 1),
  ('safety:ac', 'ac:brazing', 'پائپ کی ویلڈنگ سے پہلے کیا تیار رکھتے ہیں؟', 'Before brazing a pipe, what do you have ready?', '[{"ur": "کچھ نہیں", "en": "Nothing"}, {"ur": "آگ بجھانے والا آلہ، اور جگہ خالی اور ہوادار", "en": "A fire extinguisher, and the area clear and ventilated"}, {"ur": "شعلے کے پاس گیس سلنڈر", "en": "A gas cylinder next to the flame"}]'::jsonb, 1),
